import Foundation

struct DisposalProjectionEmbeddedResourceSpecification: Equatable, Sendable {
    let leaf: String
    let bytes: Int
    let sha256: String
}

enum DisposalProjectionEmbeddedResources {
    static let packDomain = "ergentics-disposal-embedded-rule-resource-pack-v1"
    static let packCommitmentSHA256 = "a35466c0d654c9d9c8c3da3b86fb886d1d01ce4f4487d84bdd57b46031f70f51"
    static let specifications: [DisposalProjectionEmbeddedResourceSpecification] = [
        .init(
            leaf: "001-evidence.sql",
            bytes: 50_706,
            sha256: "f3e003136aa4f9a12308d310ffa6bc92d71bccb99a7a50656c32231b79a435c7"),
        .init(
            leaf: "001-graph.sql",
            bytes: 41_517,
