            sha256: "eda615d5bc71246c54d7335679f641646e11c8938ef01a459cf168be2aa5ce61"),
        .init(
            leaf: "disposal-adapters.v1.json",
            bytes: 4_610,
            sha256: "68e09200dd29a47fcbe49e083df41fe55ead950198edf75300ab6e302b61be1b"),
        .init(
            leaf: "disposal-lattice.v1.json",
            bytes: 1_937,
            sha256: "c99361cb2052032e176b1ab5cd22898a67231b98bdea8c972388bdeab12ba022"),
    ]

    static func exact() throws -> DisposalProjectionRuleResources {
        let result = DisposalProjectionRuleResources(
            evidenceDDL: try decode(specifications[0], chunks: evidenceBase64Chunks),
            graphDDL: try decode(specifications[1], chunks: graphBase64Chunks),
            metricsDDL: try decode(specifications[2], chunks: metricsBase64Chunks),
            adapters: try decode(specifications[3], chunks: adaptersBase64Chunks),
            lattice: try decode(specifications[4], chunks: latticeBase64Chunks))
        try validate(result)
        return result
    }

    static func data(_ name: String, extension extensionName: String) throws -> Data {
        let leaf = name + "." + extensionName
        guard let index = specifications.firstIndex(where: { $0.leaf == leaf }) else {
            throw DisposalProjectionRejection(code: "RESOURCE_ABSENT", detail: leaf)
        }
        let chunks: [String]
        switch index {
        case 0: chunks = evidenceBase64Chunks
        case 1: chunks = graphBase64Chunks
        case 2: chunks = metricsBase64Chunks
        case 3: chunks = adaptersBase64Chunks
        case 4: chunks = latticeBase64Chunks
        default:
            throw DisposalProjectionRejection(code: "RESOURCE_INDEX", detail: leaf)
        }
        return try decode(specifications[index], chunks: chunks)
    }

    static func validate(_ resources: DisposalProjectionRuleResources) throws {
        let values = [
            resources.evidenceDDL, resources.graphDDL, resources.metricsDDL,
            resources.adapters, resources.lattice,
        ]
        try disposalRequireProjection(
            values.count == specifications.count,
            "EMBEDDED_RESOURCE_COUNT")
        var components: [String] = []
        for (specification, value) in zip(specifications, values) {
            let digest = disposalSHA256(value)
            try disposalRequireProjection(
                value.count == specification.bytes && digest == specification.sha256,
                "EMBEDDED_RESOURCE_IDENTITY",
                detail: specification.leaf)
            components.append(contentsOf: [
                specification.leaf, String(value.count), digest,
            ])
        }
        try disposalRequireProjection(
            disposalLengthFramedID(packDomain, components) == packCommitmentSHA256,
            "EMBEDDED_RESOURCE_PACK_COMMITMENT")
    }

    private static func decode(
        _ specification: DisposalProjectionEmbeddedResourceSpecification,
        chunks: [String]
    ) throws -> Data {
        let encoded = chunks.joined()
        guard let decoded = Data(base64Encoded: encoded, options: []),
              decoded.base64EncodedString() == encoded
        else {
            throw DisposalProjectionRejection(
                code: "EMBEDDED_RESOURCE_BASE64",
                detail: specification.leaf)
        }
        try disposalRequireProjection(
            decoded.count == specification.bytes &&
                disposalSHA256(decoded) == specification.sha256,
            "EMBEDDED_RESOURCE_DECODED_IDENTITY",
            detail: specification.leaf)
        return decoded
    }

